window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c76a4c2bd8904c5c"]={"versions": [{"id": "FIG-c76a4c2bd8904c5c", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfiguration (BSW-Modul Crypto Service Manager, CSM). Das Diagramm spezifiziert die Konfigurationsstruktur der Schlüssel (<code>CsmKeys</code>) und deren Zuordnung zur Crypto Interface Schicht (<code>CryIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>CsmKeys</strong> (<code>EcucParamConfContainerDef</code>): Wurzelcontainer für CSM-Schlüsseldefinitionen, Multiplizität 0..1.</li>\n<li>Enthält über die Komposition <code>+subContainer</code> den Container <strong>CsmKey</strong> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n<li><strong>CsmKey</strong> (<code>EcucParamConfContainerDef</code>): Repräsentiert einen logischen CSM-Schlüssel. Enthält:</li>\n<li><code>+parameter</code> <strong>CsmKeyId</strong> (<code>EcucIntegerParamDef</code>): Eindeutige numerische ID des Schlüssels mit Wertebereich <code>min = 0</code>, <code>max = 4294967295</code> (32-Bit Unsigned Integer).</li>\n<li><code>+parameter</code> <strong>CsmKeyUsePort</strong> (<code>EcucBooleanParamDef</code>): Schalter zur Aktivierung portbasierter Schnittstellen für den Schlüssel.</li>\n<li><code>+reference</code> <strong>CsmKeyRef</strong> (<code>EcucSymbolicNameReferenceDef</code>): Symbolische Referenz auf die zugeordnete Schlüsselkonfiguration der unteren Schicht.</li>\n<li><strong>CryIfKey</strong> (<code>EcucParamConfContainerDef</code>, Herkunft <code>from CryIf</code>): Zielcontainer (<code>+destination</code>), auf den <code>CsmKeyRef</code> verweist; Multiplizität 0..*.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurations- und Metamodellstruktur. Es ist kein dynamisches Laufzeit- oder Sequenzverhalten dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konfigurationsvorgabe für AUTOSAR CSM-Generatoren und BSW-Konfiguratoren.</li>\n<li>Schlüssel werden im CSM konfiguriert und verweisen mittels symbolischer Namensreferenz (<code>EcucSymbolicNameReferenceDef</code>) auf einen Schlüssel im Crypto Interface (<code>CryIfKey</code>).</li>\n<li>Der Wertebereich von <code>CsmKeyId</code> erfordert einen 32-Bit-Ganzzahldatentyp (<code>uint32</code>).</li>\n<li><code>CsmKeyUsePort</code> bestimmt, ob für den entsprechenden Schlüssel AUTOSAR-Ports generiert werden.</li>\n</ul>"}, {"id": "FIG-70bf66cfff8453a4", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfiguration (BSW-Modul Crypto Service Manager, CSM). Das Diagramm spezifiziert die Konfigurationsstruktur der Schlüssel (<code>CsmKeys</code>) und deren Zuordnung zur Crypto Interface Schicht (<code>CryIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>CsmKeys</strong> (<code>EcucParamConfContainerDef</code>): Wurzelcontainer für CSM-Schlüsseldefinitionen, Multiplizität 0..1.</li>\n<li>Enthält über die Komposition <code>+subContainer</code> den Container <strong>CsmKey</strong> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*).</li>\n<li><strong>CsmKey</strong> (<code>EcucParamConfContainerDef</code>): Repräsentiert einen logischen CSM-Schlüssel. Enthält:</li>\n<li><code>+parameter</code> <strong>CsmKeyId</strong> (<code>EcucIntegerParamDef</code>): Eindeutige numerische ID des Schlüssels mit <code>symbolicNameValue = true</code> und Wertebereich <code>min = 0</code>, <code>max = 4294967295</code>.</li>\n<li><code>+parameter</code> <strong>CsmKeyUsePort</strong> (<code>EcucBooleanParamDef</code>): Schalter zur Aktivierung portbasierter Schnittstellen für den Schlüssel.</li>\n<li><code>+reference</code> <strong>CsmKeyRef</strong> (<code>EcucReferenceDef</code>): Referenzdefinition mit <code>requiresSymbolicNameValue = true</code> auf die zugeordnete Schlüsselkonfiguration.</li>\n<li><strong>CryIfKey</strong> (<code>EcucParamConfContainerDef</code>): Zielcontainer (<code>+destination</code>), auf den <code>CsmKeyRef</code> verweist; Multiplizität 0..*.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurations- und Metamodellstruktur. Es ist kein dynamisches Laufzeit- oder Sequenzverhalten dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konfigurationsvorgabe für AUTOSAR CSM-Generatoren und BSW-Konfiguratoren.</li>\n<li>Schlüssel werden im CSM konfiguriert und verweisen über eine allgemeine Referenzdefinition (<code>EcucReferenceDef</code>), die explizit einen symbolischen Namen verlangt (<code>requiresSymbolicNameValue = true</code>), auf den Zielcontainer <code>CryIfKey</code>.</li>\n<li><code>CsmKeyId</code> dient explizit als symbolischer Name (<code>symbolicNameValue = true</code>) mit Wertebereich als 32-Bit-Ganzzahl (<code>uint32</code>).</li>\n<li><code>CsmKeyUsePort</code> bestimmt, ob für den entsprechenden Schlüssel AUTOSAR-Ports generiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-c76a4c2bd8904c5c", "to": "FIG-70bf66cfff8453a4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>CsmKeyId</code>: Attribut <code>symbolicNameValue = true</code> hinzugefügt.</li>\n<li><code>CsmKeyRef</code>: Typ von <code>EcucSymbolicNameReferenceDef</code> zu <code>EcucReferenceDef</code> geändert und Attribut <code>requiresSymbolicNameValue = true</code> ergänzt.</li>\n<li><code>CryIfKey</code>: Paket- bzw. Modulherkunftsangabe <code>(from CryIf)</code> entfernt.</li>\n</ul>"}]};
